/** BYOK soft gate: preflight hint when probe says the user's model may lack tool
 * calling. Transport-only — not journaled. */
export interface TurnWarningPayload {
  message: string;
}

/** 3D position on the town ground plane (Y-up wire coordinates).
 * 
 * - ``x``: east (+) / west (-)
 * - ``y``: height above ground (NPCs typically 0)
 * - ``z``: south (+) / north (-) */
export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

/** Per-agent snapshot on `sim.agent_state` and in tick snapshots. */
export interface SimAgentState {
  agent_id: string;
  name: string;
  role: string;
  location: string;
  position: Vec3;
  activity: string;
  mood: number;
  goal: string;
  last_thought: string;
  relationships?: Record<string, number>;
  tick_memories?: string[];
  money?: number;
  inventory?: Record<string, number>;
}

/** One agent decision within a tick (`sim.agent_action`). */
export interface SimAgentAction {
  agent_id: string;
  action: "move_to" | "stay_here" | "speak_to" | "propose_trade" | "propose_vote" | "idle" | "error";
  thought: string;
  tool_name?: string | null;
  tool_args?: Record<string, unknown> | null;
  success: boolean;
  detail: string;
}

export interface SimTickStartedPayload {
  run_id: string;
  tick: number;
  hour: number;
}

/** Macro indicators for one simulation tick (backend `TickMetrics`), carried on
 * `sim.tick_ended` for the 观测面板. `population_by_region` maps a region name →
 * head count. */
export interface SimTickMetrics {
  tick: number;
  hour: number;
  avg_mood: number;
  trade_count: number;
  trade_total_amount: number;
  positive_relation_ratio: number;
  population_by_region: Record<string, number>;
}

export interface SimTickEndedPayload {
  run_id: string;
  tick: number;
  hour: number;
  agent_count: number;
  metrics?: SimTickMetrics | null;
}

/** One persisted world frame on tick replay (``simulation/service.py`` replay path).
 * `snapshot` is the verbatim ``SimTickSnapshot`` dump persisted on the tick row. */
export interface SimTickFramePayload {
  run_id: string;
  tick_number: number;
  snapshot: Record<string, unknown>;
}

export interface SimAgentStatePayload {
  run_id: string;
  tick: number;
  state: SimAgentState;
}

export interface SimAgentActionPayload {
  run_id: string;
  tick: number;
  action: SimAgentAction;
}

export interface InteractionTranscriptLine {
  speaker_id: string;
  speaker_name: string;
  text: string;
  round: number;
}

/** Summary of world mutations applied by an interaction. */
export interface InteractionStateChange {
  mood_deltas?: Record<string, number>;
  relation_deltas?: [string, string, number][];
  money_transfers?: Record<string, unknown>[];
  inventory_transfers?: Record<string, unknown>[];
  governance?: Record<string, unknown>;
}

export interface InteractionResult {
  request_id: string;
  kind: "conversation" | "trade" | "vote" | "heart_pick";
  status: "completed" | "rejected" | "failed" | "cancelled";
  initiator_id: string;
  target_id?: string | null;
  summary: string;
  transcript?: InteractionTranscriptLine[];
  state_changes?: InteractionStateChange;
  detail?: string;
}

/** Structured interaction result on ``sim.interaction``. */
export interface SimInteractionPayload {
  run_id: string;
  tick: number;
  interaction: InteractionResult;
}

/** World-level knobs affected by scheduled events. */
export interface WorldModifiersWire {
  market_price_multiplier: number;
  storm_active: boolean;
  festival_active: boolean;
  square_attraction_boost: number;
}

/** One active world event in tick snapshots. */
export interface WorldEventWire {
  event_id: string;
  kind: string;
  event_type: string;
  title: string;
  description: string;
  payload?: Record<string, unknown>;
  tick_started: number;
  duration_ticks: number;
  source: string;
}

/** ``sim.world_event`` SSE + sim_event row. */
export interface SimWorldEventPayload {
  run_id: string;
  tick: number;
  event: WorldEventWire;
  modifiers: WorldModifiersWire;
}

/** 恋综心动选票（密封或已揭晓） on `sim.show.heart_pick`. */
export interface SimShowHeartPickPayload {
  run_id: string;
  tick: number;
  from_agent_id: string;
  to_agent_id: string;
  public: boolean;
  meta?: Record<string, unknown> | null;
}

/** 恋综互选配对 on `sim.show.pair_formed`. */
export interface SimShowPairFormedPayload {
  run_id: string;
  tick: number;
  agent_a_id: string;
  agent_b_id: string;
  meta?: Record<string, unknown> | null;
}

/** 恋综移情标记 on `sim.show.affection_shift`. */
export interface SimShowAffectionShiftPayload {
  run_id: string;
  tick: number;
  from_agent_id: string;
  to_agent_id: string;
  kind?: string | null;
  note?: string | null;
  meta?: Record<string, unknown> | null;
}

/** 恋综零票告急 on `sim.show.zero_vote_alert`. */
export interface SimShowZeroVoteAlertPayload {
  run_id: string;
  tick: number;
  agent_id: string;
  streak?: number | null;
  meta?: Record<string, unknown> | null;
}

/** 恋综角色离场 on `sim.show.departure`. */
export interface SimShowDeparturePayload {
  run_id: string;
  tick: number;
  agent_id: string;
  reason?: string | null;
  meta?: Record<string, unknown> | null;
}

/** 恋综心动揭晓一步 on `sim.show.reveal`. */
export interface SimShowRevealPayload {
  run_id: string;
  tick: number;
  who_agent_id: string;
  pick_agent_id: string;
  note?: string | null;
  meta?: Record<string, unknown> | null;
}

/** 恋综期分段 / 仪式门 on `sim.show.episode_gate`. */
export interface SimShowEpisodeGatePayload {
  run_id: string;
  tick: number;
  gate: string;
  phase?: string | null;
  meta?: Record<string, unknown> | null;
}

/** 团队浏览器直播通道状态（`browser_live_status`）：`started` 有会话且开播；
 * `no_session` 附着但无直播会话；`session_closed` 观看中的会话被回收/关闭。 */
export type BrowserLiveState = "started" | "no_session" | "session_closed";

/** One live screencast frame on `browser_live_frame`（base64 jpeg + 设备像素尺寸）. */
export interface BrowserLiveFramePayload {
  frame_b64: string;
  width: number;
  height: number;
}

/** Live channel status on ``browser_live_status`` (D14).
 * 
 * ``started`` — a live browser session exists and screencast is now flowing to viewers;
 * ``no_session`` — the viewer attached but the conversation has no live browser session;
 * ``session_closed`` — the watched session was recycled / closed (idle only when unwatched,
 * or max-lifetime). */
export interface BrowserLiveStatusPayload {
  state: BrowserLiveState;
}

/** CEO→用户「下一步推荐」: 2-4 quick-reply chips for the just-finished turn, emitted
 * after `message_end`. Persisted on `Message.followups` (DERIVED), no-op in folds.
 * `message_id` is the assistant row the chips belong to (same id as `set_followups`). */
export interface FollowupsGeneratedPayload {
  conversation_id: string;
  message_id: string;
  followups: string[];
}

/** Soft empty state when followups could not be minted (not a turn error).
 * 
 * Emitted only on failure paths with zero chips — legitimate empty model output does
 * not emit this. EPHEMERAL / fold no-op; clients show a quiet hint above the composer. */
export interface FollowupsUnavailablePayload {
  conversation_id: string;
  message_id: string;
  reason: string;
}

export interface TurnSavedPayload {
  user_message_id: string;
}

export interface Citation {
  url: string;
  title: string;
  snippet?: string;
  site?: string;
  id?: string;
  date?: string;
  tier?: string;
  query?: string;
  deep_read?: boolean;
  registrant?: string;
  citable?: boolean;
}

export interface CitationsPayload {
  citations: Citation[];
}

/** Transport-only client-tool request: apply a workspace file op on the bound
 * desktop and POST the result back. NOT journaled.
 * 
 * ``timeout_ms`` (optional): liveness budget echoed from the server channel so the
 * desktop can AbortSignal the IPC op; derived from the outer tool deadline. */
export interface WorkspaceOpRequiredPayload {
  request_id: string;
  conversation_id: string;
  root_id: string;
  op: string;
  args: Record<string, unknown>;
  timeout_ms?: number;
}

/** One structured whiteboard op (AI协作白板 M2). The closed verb set is shared with
 * the server tool + the desktop applier; fields beyond `op` are op-specific. */
export interface BoardOp {
  op: "add_node" | "connect" | "move" | "set_text" | "delete" | "group";
  ref?: string;
  id?: string;
  kind?: "sticky" | "rectangle" | "ellipse" | "diamond" | "text";
  text?: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  color?: string;
  from?: string;
  to?: string;
  label?: string;
  members?: string[];
}

/** Transport-only client-tool request: apply a batch of board ops to the open
 * whiteboard canvas (`board_id`). The board counterpart of `workspace_op_required`;
 * NOT journaled. */
export interface BoardOpRequiredPayload {
  request_id: string;
  conversation_id: string;
  board_id: string;
  ops: BoardOp[];
  summary: string;
}

/** Transport-only client-tool request: rasterize board elements (`ids`) to a PNG and
 * POST it back so the vision reader can read it. NOT journaled. */
export interface BoardReadRequiredPayload {
  request_id: string;
  conversation_id: string;
  board_id: string;
  ids: string[];
}

/** Transport-only client-tool request: show an OS notification on the bound desktop
 * (`desktop_notify` worker tool). NOT journaled. */
export interface DesktopNotifyRequiredPayload {
  request_id: string;
  conversation_id: string;
  title: string;
  body?: string;
}

/** Transport-only client-tool request: run a Host op on the bound desktop
 * (`host_*` tools). NOT journaled. */
export interface HostOpRequiredPayload {
  request_id: string;
  conversation_id: string;
  op: string;
  args?: Record<string, unknown>;
}

/** Transport-only client-tool request: run a local MCP Client op on the bound
 * desktop (stdio list_tools / call_tool). NOT journaled. */
export interface McpOpRequiredPayload {
  request_id: string;
  conversation_id: string;
  op: string;
  args?: Record<string, unknown>;
}

export interface HandoffSnapshotDonePayload {
  snapshot_id: string;
  conversation_id: string;
  size_bytes: number;
}

export interface HandoffJobStartedPayload {
  job_id: string;
  conversation_id: string;
  job_conversation_id: string;
}

export interface HandoffApplyResult {
  path: string;
  status: "applied" | "skipped" | "conflict" | "error";
  change_type: "added" | "modified" | "deleted" | null;
  detail: string;
}

export interface HandoffApplyDonePayload {
  job_id: string;
  conversation_id: string;
  results: HandoffApplyResult[];
  applied: number;
  skipped: number;
  conflicts: number;
  errors: number;
}

